SELECT Last.*, IIf([UltimoDiClose]>[last].[s5],([StrategyLine]![W20]*[StrategyLine]![S5]*100),0) AS L5, IIf([UltimoDiClose]>[last].[s10],([StrategyLine]![W20]*[StrategyLine]![S10]*100),0) AS L10, IIf([UltimoDiClose]>[last].[s15],([StrategyLine]![W20]*[StrategyLine]![S15]*100),0) AS L15, IIf([UltimoDiClose]>[last].[s20],([StrategyLine]![W20]*[StrategyLine]![S20]*100),0) AS L20, IIf([UltimoDiClose]>[last].[s50],([StrategyLine]![W50]*[StrategyLine]![S50]*100),0) AS L50, IIf([UltimoDiClose]>[last].[s100],([StrategyLine]![W100]*[StrategyLine]![S100]*100),0) AS L100, IIf([UltimoDiClose]>[last].[s200],([StrategyLine]![W200]*[StrategyLine]![S200]*100),0) AS L200, IIf([UltimoDiClose]>[last].[E5],([StrategyLine]![W20]*[StrategyLine]![E5]*100),0) AS LE5, IIf([UltimoDiClose]>[last].[E10],([StrategyLine]![W20]*[StrategyLine]![E10]*100),0) AS LE10, IIf([UltimoDiClose]>[last].[E15],([StrategyLine]![W20]*[StrategyLine]![E15]*100),0) AS LE15, IIf([UltimoDiClose]>[last].[E20],([StrategyLine]![W20]*[StrategyLine]![E20]*100),0) AS LE20, IIf([UltimoDiClose]>[last].[E50],([StrategyLine]![W50]*[StrategyLine]![E50]*100),0) AS LE50, IIf([UltimoDiClose]>[last].[E100],([StrategyLine]![W100]*[StrategyLine]![E100]*100),0) AS LE100, IIf([UltimoDiClose]>[last].[E200],([StrategyLine]![W200]*[StrategyLine]![E200]*100),0) AS LE200, IIf([last].[E20]>[last].[s20],([StrategyLine]![W20]*[StrategyLine]![E20/S20]*100),0) AS LES20, IIf([last].[E50]>[last].[s50],([StrategyLine]![W50]*[StrategyLine]![E50/S50]*100),0) AS LES50, IIf([last].[E100]>[last].[s100],([StrategyLine]![W100]*[StrategyLine]![E100/S100]*100),0) AS LES100, IIf([last].[E200]>[last].[s200],([StrategyLine]![W200]*[StrategyLine]![E200/S200]*100),0) AS LES200, IIf([last].[S20]>[last].[s50],([StrategyLine]![W50]*[StrategyLine]![S20/S50]*100),0) AS LSS50, IIf([last].[S20]>[last].[s100],([StrategyLine]![W100]*[StrategyLine]![S20/S100]*100),0) AS LSS20S100, IIf([last].[S50]>[last].[s100],([StrategyLine]![W100]*[StrategyLine]![S50/S100]*100),0) AS LSS50S100, IIf([last].[S20]>[last].[s200],([StrategyLine]![W200]*[StrategyLine]![S20/S200]*100),0) AS LSS20S200, IIf([last].[S50]>[last].[s200],([StrategyLine]![W200]*[StrategyLine]![S50/S200]*100),0) AS LSS50S200, IIf([last].[S100]>[last].[s200],([StrategyLine]![W200]*[StrategyLine]![S100/S200]*100),0) AS LSS100S200, [L5]+[LE5] AS T5, [L10]+[LE10] AS T10, [L15]+[LE15] AS T15, [L20]+[LE20]+[LES20] AS T20, [L50]+[LE50]+[LES50]+[LSS50] AS T50, [L100]+[LE100]+[LES100]+[LSS20S100]+[LSS50S100] AS T100, [L200]+[LE200]+[LES200]+[LSS20S200]+[LSS50S200]+[LSS100S200] AS T200, [T5]+[T10]+[T15]+[T20]+[T50]+[T100]+[T200] AS TT
FROM HistoricPriceEMALast AS [Last], StrategyLine;
